--         against pg_policies / pg_get_expr / pg_class / aclexplode / pg_default_acl.
--
-- Purpose: restore the authoritative public-schema RLS policies (206) and the view ACLs that
--          the authoritative baseline (20260000000000_authoritative_baseline.sql) intentionally
--          omitted. This file is placed intentionally EARLY in the migration chain, immediately
--          after the baseline, so that later feature migrations can override policies.
--
-- All 206 production public policies are accounted for: 200 are created here with roles/cmd/
-- expressions verbatim (USING/WITH CHECK bodies unchanged; pg_get_expr newlines folded to
-- spaces) under idempotent IF NOT EXISTS guards; the remaining 6 are DROP-only guards because
-- later migrations own their names (see Conflict notes). Seven production owns_* helper functions
-- referenced by the policies but missing from local migrations are also reproduced verbatim.
-- No business data is inserted. DO NOT APPLY TO PRODUCTION.
--
-- Conflict notes: six policy names are also created by later migrations with a bare
-- CREATE POLICY (no DROP guard): the four gallery_images policies in
-- 20260916000001_fix_broken_endpoints.sql and the two payment_receipts policies in
-- 20261002000002_payment_receipts_table.sql. For those names this file emits only a
-- DROP POLICY IF EXISTS guard (no CREATE), leaving the production-equivalent definition to
-- the later migration; see the "LATER-MIGRATION-OWNED" markers below.
--
-- View ACLs: in production anon lacks SELECT on cart_items_detailed (anon=m),
-- cart_totals (anon=m) and order_item_print_files (anon=awdDxtm); authenticated has
-- SELECT on the two cart views, service_role keeps ALL. Local default privileges grant
-- ALL to anon on new views, so those privileges are explicitly revoked here. No grants
-- are widened beyond the production catalog.

set search_path = public, extensions;

-- ============================================================================
-- 0. HELPER FUNCTIONS REQUIRED BY THE AUTHORITATIVE POLICIES
--    Production catalog (pg_get_functiondef, read-only 2026-11-18). These six
--    owns_* functions are referenced by production policies but are absent from
--    every local migration, so the policies cannot be created without them.
--    Reproduced verbatim; later migrations may replace them freely.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.owns_customization(target_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case
    when public.is_admin() then true
    else exists (select 1 from public.product_customizations where id = target_id and owner_id = auth.uid())
  end;
$function$;

CREATE OR REPLACE FUNCTION public.owns_notification(target_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case
    when public.is_admin() then true
    else exists (select 1 from public.notifications where id = target_id and user_id = auth.uid())
  end;
$function$;

CREATE OR REPLACE FUNCTION public.owns_payment(target_payment_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case
    when public.is_admin() then true
    else exists (
      select 1 from public.payments p join public.orders o on o.id = p.order_id
      where p.id = target_payment_id and o.user_id = auth.uid()
    )
  end;
$function$;

CREATE OR REPLACE FUNCTION public.owns_review(target_review_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case
    when public.is_admin() then true
    else exists (select 1 from public.reviews where id = target_review_id and user_id = auth.uid() and deleted_at is null)
  end;
$function$;

CREATE OR REPLACE FUNCTION public.owns_shipment(target_shipment_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case
    when public.is_admin() then true
    else exists (
      select 1 from public.shipments s join public.orders o on o.id = s.order_id
      where s.id = target_shipment_id and o.user_id = auth.uid()
    )
  end;
$function$;

CREATE OR REPLACE FUNCTION public.owns_wallet(target_wallet_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case
    when public.is_admin() then true
    else exists (select 1 from public.wallets where id = target_wallet_id and user_id = auth.uid())
  end;
$function$;

CREATE OR REPLACE FUNCTION public.owns_wishlist(target_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case
    when public.is_admin() then true
    else exists (select 1 from public.wishlists where id = target_id and owner_id = auth.uid() and deleted_at is null)
  end;
$function$;

