-- ============================================================================
-- 2. AUTHORITATIVE VIEW ACLs (production catalog 2026-11-18)
--    Production: cart_items_detailed / cart_totals => anon=m (NO SELECT),
--    authenticated=rm, service_role=arwdDxtm; order_item_print_files => anon=awdDxtm
--    (NO SELECT), authenticated=arwdDxtm, service_role=arwdDxtm.
--    Local defaults grant ALL to anon, so revoke from PUBLIC/anon and re-grant exactly the
--    production privileges to authenticated and service_role. No grants are widened.
-- ============================================================================

DO $grants$ BEGIN
  IF to_regclass('public.cart_items_detailed') IS NOT NULL THEN
    REVOKE ALL ON TABLE public.cart_items_detailed FROM PUBLIC, anon;
    GRANT SELECT, MAINTAIN ON TABLE public.cart_items_detailed TO authenticated;
    GRANT ALL ON TABLE public.cart_items_detailed TO service_role;
  END IF;
  IF to_regclass('public.cart_totals') IS NOT NULL THEN
    REVOKE ALL ON TABLE public.cart_totals FROM PUBLIC, anon;
    GRANT SELECT, MAINTAIN ON TABLE public.cart_totals TO authenticated;
    GRANT ALL ON TABLE public.cart_totals TO service_role;
  END IF;
  IF to_regclass('public.order_item_print_files') IS NOT NULL THEN
    REVOKE ALL ON TABLE public.order_item_print_files FROM PUBLIC, anon;
    GRANT ALL ON TABLE public.order_item_print_files TO authenticated, service_role;
  END IF;
END $grants$;

-- End of authoritative RLS and grants migration.
